"""Command-line interface."""
import sys

from inventory.diff import compare
from inventory.loader import load_stock


def main(argv):
    if len(argv) != 2:
        print("usage: python3 -m inventory OLD.json NEW.json", file=sys.stderr)
        return 2
    try:
        differences = compare(load_stock(argv[0]), load_stock(argv[1]))
    except (OSError, ValueError) as err:
        print(f"error: {err}", file=sys.stderr)
        return 1
    for diff in differences:
        print(f"{diff.sku:<10} {diff.kind:<8} {diff.old} -> {diff.new}")
    return 0

